def encrypt(text, n):
    if not text or n <= 0:
        return text
    for _ in range(n):
        text = text[1::2] + text[::2]
    return text

def decrypt(encrypted_text, n):
    if not encrypted_text or n <= 0:
        return encrypted_text
    length = len(encrypted_text)
    half = (length + 1) // 2
    for _ in range(n):
        even_chars = encrypted_text[:half]
        odd_chars = encrypted_text[half:]
        decrypted = [''] * length
        decrypted[1::2] = even_chars
        decrypted[::2] = odd_chars
        encrypted_text = ''.join(decrypted)
    return encrypted_text
